import React, { useState } from "react";
import Button from "@mui/material/Button";
import { AiOutlineMenuFold, AiOutlineMenuUnfold } from "react-icons/ai";

function HeaderPage() {
  const [menuOpen, setMenuOpen] = useState(false);

  const handleMenuToggle = () => {
    setMenuOpen(!menuOpen);
  };

  return (
    <header className="w-full h-[70px] shadow-md bg-[#1e88e5] text-white flex items-center justify-between px-6">
      {/* Left Section: Menu Button */}
      <div className="flex items-center h-full">
        <Button
          onClick={handleMenuToggle}
          sx={{
            width: 42,
            height: 42,
            minWidth: 42,
            borderRadius: "50%",
            backgroundColor: "rgba(255,255,255,0.2)",
            "&:hover": { backgroundColor: "rgba(255,255,255,0.3)" },
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {menuOpen ? (
            <AiOutlineMenuUnfold size={22} color="#fff" />
          ) : (
            <AiOutlineMenuFold size={22} color="#fff" />
          )}
        </Button>
      </div>

      {/* Center Title */}
      <div className="flex-1 flex justify-center items-center">
        <h1 className="text-xl font-semibold tracking-wide drop-shadow-md text-center">
          My Dashboard
        </h1>
      </div>

      {/* Right Section: Sign-in Button */}
      <div className="flex items-center h-full justify-end">
        <Button
          variant="contained"
          sx={{
            backgroundColor: "#ff5252",
            color: "#fff",
            textTransform: "none",
            px: 3,
            py: 1,
            borderRadius: "8px",
            boxShadow: 3,
            "&:hover": { backgroundColor: "#ff7070" },
          }}
        >
          Sign in
        </Button>
      </div>
    </header>
  );
}

export default HeaderPage;
